package com.bank.facalloc.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Greedy two-pointer: give the smallest facility that satisfies each applicant.
public class FacilityAllocationService {
    private static final Logger log = Logger.getLogger(FacilityAllocationService.class.getName());

    public int maxSatisfied(int[] minimums, int[] facilitySizes) {
        Arrays.sort(minimums);                             // least demanding first
        Arrays.sort(facilitySizes);                        // smallest facility first
        int i = 0, j = 0, happy = 0;
        while (i < minimums.length && j < facilitySizes.length) {
            if (facilitySizes[j] >= minimums[i]) {         // this facility satisfies applicant i
                happy++;
                i++;                                        // move to next applicant
            }
            j++;                                            // this facility is now used/too small
        }
        final int result = happy;
        log.info(() -> "Applicants satisfied = " + result);
        return happy;
    }
}
