package com.bank.facalloc;

import com.bank.facalloc.service.FacilityAllocationService;
import java.util.logging.Logger;

public class FacilityAllocationApplication {
    private static final Logger log = Logger.getLogger(FacilityAllocationApplication.class.getName());

    public static void main(String[] args) {
        FacilityAllocationService service = new FacilityAllocationService();
        int[] minimums = {1, 2, 3};                        // minimum facility each applicant needs
        int[] facilities = {1, 1};                         // available facility sizes
        int satisfied = service.maxSatisfied(minimums, facilities);
        log.info(() -> "Final satisfied count = " + satisfied);
    }
}
